use vstd::prelude::*;

verus! {
    /// Append `elem` to the end of vector `v`.
    /// 
    /// Ensures that the returned Vec’s logical contents (`@`‐notation)
    /// are exactly `v@ ++ seq![elem]`.
    fn append(v: &Vec<u64>, elem: u64) -> Vec<u64>
        ensures
            // length has grown by exactly one
            result.len() == v.len() + 1,
            // the abstract view of result is exactly v@ with elem appended
            result@ == v@ + seq![elem],
    {
        // Pre-allocate a new vector with the required capacity
        let mut result = Vec::with_capacity(v.len() + 1);

        // Copy over all existing elements
        result.extend_from_slice(v);

        // Append the new element
        result.push(elem);

        result
    }
}

